CREATE POLICY op_mo_technician_update ON public.op_maintenance_orders FOR UPDATE TO authenticated USING (assigned_technician_id IN (SELECT t.id FROM public.op_maint_technicians t WHERE t.user_id = auth.uid() AND t.organization_id = op_maintenance_orders.organization_id)) WITH CHECK (assigned_technician_id IN (SELECT t.id FROM public.op_maint_technicians t WHERE t.user_id = auth.uid() AND t.organization_id = op_maintenance_orders.organization_id)); CREATE POLICY op_mo_technician_select ON public.op_maintenance_orders FOR SELECT TO authenticated USING (assigned_technician_id IN (SELECT t.id FROM public.op_maint_technicians t WHERE t.user_id = auth.uid() AND t.organization_id = op_maintenance_orders.organization_id));